// Synthetic "Path to Port" dataset for Rotterdam — a realistic large-scale
// scenario (~300 inbound vessels) used only by Path to Port v8 to demonstrate
// how the density slider + advanced filters behave when hundreds of ships are
// converging on one port. Rows are fully deterministic (seeded), so a given
// vessel always shows the same position/type/flag/name across renders.
//
// Positions are generated by picking a bearing + distance from the port and
// projecting a great-circle destination, so every vessel has a plausible
// distance-to-port and the route line has real coordinates to draw. Bearings are
// biased toward open water (Channel / North Sea approaches) rather than inland.

import { haversineNm } from '../utils/pathToPort'

// Rotterdam port center (matches PROTOTYPE_PORTS entry).
const ROTTERDAM = { lng: 4.05, lat: 51.95 }
const EARTH_RADIUS_NM = 3440.065

// Small deterministic PRNG (mulberry32) so the dataset is stable across reloads.
const mulberry32 = (seed) => {
  let a = seed >>> 0
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const toRad = (deg) => (deg * Math.PI) / 180
const toDeg = (rad) => (rad * 180) / Math.PI

// Destination point given a start, an initial bearing (deg) and a distance (nm).
const destinationPoint = (start, bearingDeg, distanceNm) => {
  const delta = distanceNm / EARTH_RADIUS_NM
  const theta = toRad(bearingDeg)
  const phi1 = toRad(start.lat)
  const lambda1 = toRad(start.lng)
  const sinPhi2 =
    Math.sin(phi1) * Math.cos(delta) +
    Math.cos(phi1) * Math.sin(delta) * Math.cos(theta)
  const phi2 = Math.asin(sinPhi2)
  const y = Math.sin(theta) * Math.sin(delta) * Math.cos(phi1)
  const x = Math.cos(delta) - Math.sin(phi1) * sinPhi2
  const lambda2 = lambda1 + Math.atan2(y, x)
  return {
    lat: toDeg(phi2),
    lng: (((toDeg(lambda2) + 540) % 360) - 180),
  }
}

// Realistic Rotterdam traffic mix (weighted so container/bulk/tanker dominate).
const SHIP_TYPES = [
  ['Container Ship', 30],
  ['Bulk Carrier', 20],
  ['Crude Oil Tanker', 12],
  ['Chemical Tanker', 10],
  ['Oil/Chemical Tanker', 6],
  ['LNG Tanker', 4],
  ['LPG Tanker', 4],
  ['Vehicle Carrier', 5],
  ['General Cargo', 5],
  ['Reefer', 2],
  ['Ro-Ro Cargo', 2],
]

// Common open-registry + European flags (emoji only to match the table's flag
// column; the weight biases toward the big registries).
const FLAGS = [
  ['🇵🇦', 16],
  ['🇱🇷', 14],
  ['🇲🇭', 13],
  ['🇸🇬', 8],
  ['🇲🇹', 8],
  ['🇨🇾', 5],
  ['🇬🇷', 5],
  ['🇭🇰', 5],
  ['🇨🇳', 5],
  ['🇩🇰', 4],
  ['🇳🇱', 4],
  ['🇩🇪', 3],
  ['🇳🇴', 3],
  ['🇬🇧', 3],
  ['🇮🇹', 2],
  ['🇧🇸', 2],
  ['🇵🇹', 2],
]

const NAME_PREFIX = [
  'Nordic', 'Atlantic', 'Pacific', 'Ocean', 'Cape', 'Silver', 'Golden', 'Blue',
  'Iron', 'Grand', 'Royal', 'Northern', 'Southern', 'Crystal', 'Pioneer',
  'Horizon', 'Meridian', 'Aurora', 'Vega', 'Orion', 'Polaris', 'Aegean',
  'Baltic', 'Adriatic', 'Arctic', 'Coral', 'Amber', 'Jade', 'Onyx', 'Titan',
  'Neptune', 'Triton', 'Zephyr', 'Ever', 'Cosco', 'Bright', 'Star', 'Marea',
]
const NAME_SUFFIX = [
  'Star', 'Trader', 'Voyager', 'Express', 'Spirit', 'Pioneer', 'Carrier',
  'Mariner', 'Navigator', 'Endeavour', 'Pearl', 'Falcon', 'Horizon', 'Dawn',
  'Crown', 'Glory', 'Wave', 'Bridge', 'Runner', 'Breeze', 'Sky', 'River',
  'Bay', 'Sea', 'Guardian', 'Explorer', 'Venture', 'Moon', 'Sun', 'Phoenix',
]

const weightedPick = (rng, table) => {
  const total = table.reduce((sum, [, w]) => sum + w, 0)
  let r = rng() * total
  for (const [value, w] of table) {
    r -= w
    if (r <= 0) return value
  }
  return table[table.length - 1][0]
}

const buildRows = (count) => {
  const rng = mulberry32(0x52_54_4d_00) // "RTM"
  const rows = []
  const usedNames = new Set()
  for (let i = 0; i < count; i += 1) {
    // Distance mixture: mostly regional (Channel / North Sea), a long-haul tail.
    const roll = rng()
    let distanceNm
    if (roll < 0.55) distanceNm = 20 + rng() * 480 // 20–500 nm
    else if (roll < 0.85) distanceNm = 500 + rng() * 1300 // 500–1800 nm
    else distanceNm = 1800 + rng() * 4700 // 1800–6500 nm

    // Bias bearings toward open-water approaches: SW → W → N (Channel + North
    // Sea), wrapping past 360 into a little NNE. Avoids projecting inland (east).
    const bearing = (235 + rng() * 150) % 360 // ~235°–385° → 235..360 & 0..25
    const pos = destinationPoint(ROTTERDAM, bearing, distanceNm)

    let name
    do {
      name = `${NAME_PREFIX[Math.floor(rng() * NAME_PREFIX.length)]} ${
        NAME_SUFFIX[Math.floor(rng() * NAME_SUFFIX.length)]
      }`
    } while (usedNames.has(name) && usedNames.size < 900)
    usedNames.add(name)

    const shipId = `rtm-${String(i + 1).padStart(3, '0')}`
    const mmsi = String(200000000 + Math.floor(rng() * 99999999))
    const imo = String(9000000 + Math.floor(rng() * 999999))
    rows.push({
      id: `arrival-${shipId}`,
      shipId,
      detectionId: null,
      name,
      flag: weightedPick(rng, FLAGS),
      type: weightedPick(rng, SHIP_TYPES),
      imo,
      mmsi,
      position: { lng: pos.lng, lat: pos.lat },
      distanceNm: haversineNm(pos, ROTTERDAM),
    })
  }
  return rows
}

// Generate once (module-level) and reuse; slicing gives smaller sets for callers
// that only want a handful (non-v8 versions).
const ALL_ROTTERDAM_ROWS = buildRows(300)

export const getRotterdamArrivalBaseRows = (count = 300) =>
  count >= ALL_ROTTERDAM_ROWS.length
    ? ALL_ROTTERDAM_ROWS
    : ALL_ROTTERDAM_ROWS.slice(0, count)

export const isRotterdamPort = (tab) => {
  if (!tab) return false
  const id = String(tab.id || '')
    .trim()
    .toLowerCase()
  if (id === 'port-rotterdam') return true
  const name = String(tab.name || '')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '')
  return name === 'rotterdam'
}
